CREATE OR REPLACE FUNCTION public.guard_agent_model() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.model IS NOT NULL AND NEW.model NOT IN ('fast','balanced','advanced','openai/chat-latest','openai/gpt-5.4','openai/gpt-5.4-mini','openai/gpt-5.5','openai/gpt-5.6-luna','openai/gpt-5.6-sol','openai/gpt-5.6-terra','openai/gpt-6-astra') THEN RAISE EXCEPTION 'Unsupported chat model'; END IF; RETURN NEW; END $$;
ALTER TABLE public.conversations ADD COLUMN IF NOT EXISTS entry_source text NOT NULL DEFAULT 'legacy';
ALTER TABLE public.conversations ADD CONSTRAINT conversations_entry_source_check CHECK(entry_source IN ('legacy','incoming_message','incoming_form','test'));
CREATE TABLE public.support_ticket_messages(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), ticket_id uuid NOT NULL REFERENCES public.support_requests(id) ON DELETE CASCADE, sender_id uuid, sender_role text NOT NULL CHECK(sender_role IN ('requester','admin')), body text NOT NULL CHECK(length(btrim(body)) BETWEEN 1 AND 4000), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT ON public.support_ticket_messages TO authenticated; GRANT ALL ON public.support_ticket_messages TO service_role;
ALTER TABLE public.support_ticket_messages ENABLE ROW LEVEL SECURITY;
CREATE POLICY "ticket participants read" ON public.support_ticket_messages FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.support_requests s WHERE s.id=ticket_id AND (s.user_id=auth.uid() OR public.has_role(auth.uid(),'admin') OR (s.artist_id IS NOT NULL AND public.is_artist_team(s.artist_id)))));
CREATE POLICY "ticket participants send" ON public.support_ticket_messages FOR INSERT TO authenticated WITH CHECK(sender_id=auth.uid() AND EXISTS(SELECT 1 FROM public.support_requests s WHERE s.id=ticket_id AND s.status<>'closed' AND (s.user_id=auth.uid() OR public.has_role(auth.uid(),'admin') OR (s.artist_id IS NOT NULL AND public.is_artist_team(s.artist_id)))));
CREATE INDEX support_ticket_messages_thread_idx ON public.support_ticket_messages(ticket_id,created_at,id);
INSERT INTO public.support_ticket_messages(ticket_id,sender_id,sender_role,body,created_at) SELECT id,user_id,'requester',message,created_at FROM public.support_requests;
INSERT INTO public.support_ticket_messages(ticket_id,sender_id,sender_role,body,created_at) SELECT id,replied_by,'admin',admin_reply,coalesce(replied_at,updated_at) FROM public.support_requests WHERE nullif(btrim(admin_reply),'') IS NOT NULL;
CREATE FUNCTION public.guard_support_ticket_message() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sign in required'; END IF; NEW.sender_id:=auth.uid(); NEW.sender_role:=CASE WHEN public.has_role(auth.uid(),'admin') THEN 'admin' ELSE 'requester' END; NEW.body:=btrim(NEW.body); NEW.created_at:=now(); IF NOT EXISTS(SELECT 1 FROM public.support_requests s WHERE s.id=NEW.ticket_id AND s.status<>'closed' AND (s.user_id=auth.uid() OR public.has_role(auth.uid(),'admin') OR (s.artist_id IS NOT NULL AND public.is_artist_team(s.artist_id)))) THEN RAISE EXCEPTION 'Ticket unavailable'; END IF; RETURN NEW; END $$;
CREATE TRIGGER guard_ticket_message BEFORE INSERT ON public.support_ticket_messages FOR EACH ROW EXECUTE FUNCTION public.guard_support_ticket_message();
CREATE FUNCTION public.sync_support_ticket_reply() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.sender_role='admin' THEN UPDATE public.support_requests SET admin_reply=NEW.body WHERE id=NEW.ticket_id; END IF; RETURN NEW; END $$;
CREATE TRIGGER sync_ticket_reply AFTER INSERT ON public.support_ticket_messages FOR EACH ROW EXECUTE FUNCTION public.sync_support_ticket_reply();
CREATE TABLE public.artist_own_prompts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),artist_id uuid NOT NULL REFERENCES public.artists(id) ON DELETE CASCADE,kind text NOT NULL DEFAULT 'instruction' CHECK(kind IN ('instruction','know')),title text NOT NULL CHECK(length(btrim(title)) BETWEEN 1 AND 120),applies_when text NOT NULL DEFAULT 'Always',priority text NOT NULL DEFAULT 'medium' CHECK(priority IN ('low','medium','high')),body text NOT NULL CHECK(length(btrim(body)) BETWEEN 1 AND 500),enabled boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.artist_own_prompts TO authenticated; GRANT ALL ON public.artist_own_prompts TO service_role;
ALTER TABLE public.artist_own_prompts ENABLE ROW LEVEL SECURITY;
CREATE POLICY "owner manages personal prompts" ON public.artist_own_prompts FOR ALL TO authenticated USING(public.is_artist_owner(artist_id)) WITH CHECK(public.is_artist_owner(artist_id));
CREATE FUNCTION public.guard_own_prompt_limit() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE lim integer; BEGIN IF TG_OP='UPDATE' AND NEW.artist_id IS DISTINCT FROM OLD.artist_id THEN RAISE EXCEPTION 'Artist cannot change'; END IF; PERFORM 1 FROM public.artists WHERE id=NEW.artist_id FOR UPDATE; SELECT max_own_prompts INTO lim FROM public.plan_tiers WHERE code=public.effective_artist_plan(NEW.artist_id); IF TG_OP='INSERT' AND (lim IS NULL OR (lim>=0 AND (SELECT count(*) FROM public.artist_own_prompts WHERE artist_id=NEW.artist_id)>=lim)) THEN RAISE EXCEPTION 'Your plan personal prompt limit has been reached'; END IF; RETURN NEW; END $$;
CREATE TRIGGER own_prompt_limit BEFORE INSERT OR UPDATE ON public.artist_own_prompts FOR EACH ROW EXECUTE FUNCTION public.guard_own_prompt_limit();
REVOKE ALL ON FUNCTION public.guard_support_ticket_message(),public.sync_support_ticket_reply(),public.guard_own_prompt_limit() FROM PUBLIC,anon,authenticated;